@startuml

class RepairShop {
  + name : string
  + address : string
  + numberOfEmployees : int
}

class Employee {
  + taxCode : string
  + address : string
  + phoneNumber : string
  + yearsOfService : int
}

class Director extends Employee {
  + age : int
}

class Vehicle {
  + model : string
  + type : string
  + licensePlate : string
  + yearOfRegistration : int
  + owner : string
}

class Owner {
  + taxCode : string
  + address : string
  + phoneNumber : string
}

class Repair {
  + code : string
  + checkInDateTime : datetime
  + returnDateTime : datetime
}

class Manager {}

class AccountingOffice {}

RepairShop "1" *-- "1..*" Employee : employs
RepairShop "1" -- "1" Director : has
RepairShop "1" -- "*" Repair : performs
Vehicle "1" -- "0..*" Repair : undergoes
Vehicle "*" -- "1" Owner : owned by
Manager ..> RepairShop : analyzes
Manager ..> Employee : analyzes
Director ..> RepairShop : manages
Director ..> AccountingOffice : communicates results to

@enduml

